/* From Uiverse.io by kamehame-ha - Tags:  */
.__UIV_SCOPE__ .button {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 10px 15px;
  gap: 15px;
  background-color: #181717;
  outline: 3px #181717 solid;
  outline-offset: -3px;
  border-radius: 5px;
  border: none;
  cursor: pointer;
  transition: 400ms;
}

.__UIV_SCOPE__ .button .text {
  color: white;
  font-weight: 700;
  font-size: 1em;
  transition: 400ms;
}

.__UIV_SCOPE__ .button svg path {
  transition: 400ms;
}

.__UIV_SCOPE__ .button:hover {
  background-color: transparent;
}

.__UIV_SCOPE__ .button:hover .text {
  color: #181717;
}

.__UIV_SCOPE__ .button:hover svg path {
  fill: #181717;
}
